--
-- Name: v_activity_rollup; Type: VIEW; Schema: public; Owner: mse_app
--

CREATE VIEW public.v_activity_rollup AS
 SELECT a.project_id,
    a.kind,
    a.geo_unit_id,
    gu.name AS geo_name,
    a.program_node_id,
    pn.code AS program_code,
    (EXTRACT(year FROM a.date))::integer AS period_year,
    (EXTRACT(quarter FROM a.date))::integer AS period_quarter,
    (EXTRACT(month FROM a.date))::integer AS period_month,
    count(*) AS activity_count,
    COALESCE(sum(a.total_participants), (0)::bigint) AS participants,
    COALESCE(sum(a.women_count), (0)::bigint) AS women,
    COALESCE(sum(a.youth_count), (0)::bigint) AS youth
   FROM ((public.activities_activity a
     LEFT JOIN public.geo_geounit gu ON ((gu.id = a.geo_unit_id)))
     LEFT JOIN public.program_programnode pn ON ((pn.id = a.program_node_id)))
  WHERE ((a.status)::text = 'CONSOLIDATED'::text)
  GROUP BY a.project_id, a.kind, a.geo_unit_id, gu.name, a.program_node_id, pn.code, (EXTRACT(year FROM a.date)), (EXTRACT(quarter FROM a.date)), (EXTRACT(month FROM a.date));


ALTER VIEW public.v_activity_rollup OWNER TO mse_app;

--
-- Name: v_financial_by_category; Type: VIEW; Schema: public; Owner: mse_app
--

CREATE VIEW public.v_financial_by_category AS
 WITH spine AS (
         SELECT DISTINCT u.project_id,
            u.expense_category_id,
            u.fiscal_year
           FROM ( SELECT finance_financialtransaction.project_id,
                    finance_financialtransaction.expense_category_id,
                    finance_financialtransaction.fiscal_year
                   FROM public.finance_financialtransaction
                  WHERE ((finance_financialtransaction.expense_category_id IS NOT NULL) AND ((finance_financialtransaction.status)::text = 'CONSOLIDATED'::text))
                UNION
                 SELECT finance_budgetline.project_id,
                    finance_budgetline.expense_category_id,
                    finance_budgetline.fiscal_year
                   FROM public.finance_budgetline
                  WHERE ((finance_budgetline.expense_category_id IS NOT NULL) AND (finance_budgetline.fiscal_year IS NOT NULL))) u
        ), budget_total AS (
         SELECT finance_budgetline.project_id,
            finance_budgetline.expense_category_id,
            sum(finance_budgetline.amount) AS budget_total
           FROM public.finance_budgetline
          WHERE (finance_budgetline.expense_category_id IS NOT NULL)
          GROUP BY finance_budgetline.project_id, finance_budgetline.expense_category_id
        ), budget_annual AS (
         SELECT finance_budgetline.project_id,
            finance_budgetline.expense_category_id,
            finance_budgetline.fiscal_year,
            sum(finance_budgetline.amount) AS budget_annual
           FROM public.finance_budgetline
          WHERE ((finance_budgetline.expense_category_id IS NOT NULL) AND (finance_budgetline.fiscal_year IS NOT NULL))
          GROUP BY finance_budgetline.project_id, finance_budgetline.expense_category_id, finance_budgetline.fiscal_year
        ), tx AS (
         SELECT finance_financialtransaction.project_id,
            finance_financialtransaction.expense_category_id,
            finance_financialtransaction.fiscal_year,
            sum(finance_financialtransaction.amount) FILTER (WHERE ((finance_financialtransaction.kind)::text = 'ENGAGEMENT'::text)) AS engaged,
            sum(finance_financialtransaction.amount) FILTER (WHERE ((finance_financialtransaction.kind)::text = 'DISBURSEMENT'::text)) AS disbursed,
            sum(finance_financialtransaction.amount) FILTER (WHERE ((finance_financialtransaction.kind)::text = 'REALIZATION'::text)) AS realised
           FROM public.finance_financialtransaction
          WHERE ((finance_financialtransaction.expense_category_id IS NOT NULL) AND ((finance_financialtransaction.status)::text = 'CONSOLIDATED'::text))
          GROUP BY finance_financialtransaction.project_id, finance_financialtransaction.expense_category_id, finance_financialtransaction.fiscal_year
        )
 SELECT s.project_id,
    s.expense_category_id,
    ec.code AS category_code,
    ec.name AS category_name,
    s.fiscal_year,
    COALESCE(ba.budget_annual, (0)::numeric) AS budget_annual,
    bt.budget_total,
    COALESCE(tx.engaged, (0)::numeric) AS engaged_year,
    COALESCE(tx.disbursed, (0)::numeric) AS disbursed_year,
    COALESCE(tx.realised, (0)::numeric) AS realised_year,
    sum(COALESCE(tx.engaged, (0)::numeric)) OVER w AS engaged_cumulative,
    sum(COALESCE(tx.disbursed, (0)::numeric)) OVER w AS disbursed_cumulative,
    sum(COALESCE(tx.realised, (0)::numeric)) OVER w AS realised_cumulative,
        CASE
            WHEN ((bt.budget_total IS NULL) OR (bt.budget_total = (0)::numeric)) THEN NULL::numeric
            ELSE round(((100.0 * sum(COALESCE(tx.disbursed, (0)::numeric)) OVER w) / bt.budget_total), 1)
        END AS disbursement_rate,
        CASE
            WHEN ((bt.budget_total IS NULL) OR (bt.budget_total = (0)::numeric)) THEN NULL::numeric
            ELSE round(((100.0 * sum(COALESCE(tx.realised, (0)::numeric)) OVER w) / bt.budget_total), 1)
        END AS financial_realisation_rate,
        CASE
            WHEN (COALESCE(ba.budget_annual, (0)::numeric) = (0)::numeric) THEN NULL::numeric
            ELSE round(((100.0 * COALESCE(tx.disbursed, (0)::numeric)) / ba.budget_annual), 1)
        END AS disbursement_rate_annual,
    (bt.budget_total - sum(COALESCE(tx.disbursed, (0)::numeric)) OVER w) AS reliquat_disbursed,
    (bt.budget_total - sum(COALESCE(tx.realised, (0)::numeric)) OVER w) AS reliquat_realised
   FROM ((((spine s
     JOIN public.finance_expensecategory ec ON ((ec.id = s.expense_category_id)))
     LEFT JOIN budget_total bt ON (((bt.project_id = s.project_id) AND (bt.expense_category_id = s.expense_category_id))))
     LEFT JOIN budget_annual ba ON (((ba.project_id = s.project_id) AND (ba.expense_category_id = s.expense_category_id) AND (ba.fiscal_year = s.fiscal_year))))
     LEFT JOIN tx ON (((tx.project_id = s.project_id) AND (tx.expense_category_id = s.expense_category_id) AND (tx.fiscal_year = s.fiscal_year))))
  WINDOW w AS (PARTITION BY s.project_id, s.expense_category_id ORDER BY s.fiscal_year ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);


ALTER VIEW public.v_financial_by_category OWNER TO mse_app;

--
-- Name: v_financial_by_component; Type: VIEW; Schema: public; Owner: mse_app
--

CREATE VIEW public.v_financial_by_component AS
 WITH RECURSIVE node_root AS (
         SELECT program_programnode.id,
            program_programnode.project_id,
            program_programnode.parent_id,
            program_programnode.id AS root_id,
            program_programnode.code AS root_code,
            program_programnode.name AS root_name
           FROM public.program_programnode
          WHERE (program_programnode.parent_id IS NULL)
        UNION ALL
         SELECT n.id,
            n.project_id,
            n.parent_id,
            r.root_id,
            r.root_code,
            r.root_name
           FROM (public.program_programnode n
             JOIN node_root r ON ((n.parent_id = r.id)))
        ), spine AS (
         SELECT DISTINCT u.project_id,
            u.root_id,
            u.root_code,
            u.root_name,
            u.fiscal_year
           FROM ( SELECT t.project_id,
                    nr.root_id,
                    nr.root_code,
                    nr.root_name,
                    t.fiscal_year
                   FROM (public.finance_financialtransaction t
                     JOIN node_root nr ON ((nr.id = t.program_node_id)))
                  WHERE ((t.program_node_id IS NOT NULL) AND ((t.status)::text = 'CONSOLIDATED'::text))
                UNION
                 SELECT b.project_id,
                    nr.root_id,
                    nr.root_code,
                    nr.root_name,
                    b.fiscal_year
                   FROM (public.finance_budgetline b
                     JOIN node_root nr ON ((nr.id = b.program_node_id)))
                  WHERE ((b.program_node_id IS NOT NULL) AND (b.fiscal_year IS NOT NULL))) u
        ), budget_total AS (
         SELECT b.project_id,
            nr.root_id,
            sum(b.amount) AS budget_total
           FROM (public.finance_budgetline b
             JOIN node_root nr ON ((nr.id = b.program_node_id)))
          WHERE (b.program_node_id IS NOT NULL)
          GROUP BY b.project_id, nr.root_id
        ), tx AS (
         SELECT t.project_id,
            nr.root_id,
            t.fiscal_year,
            sum(t.amount) FILTER (WHERE ((t.kind)::text = 'DISBURSEMENT'::text)) AS disbursed,
            sum(t.amount) FILTER (WHERE ((t.kind)::text = 'REALIZATION'::text)) AS realised,
            sum(t.amount) FILTER (WHERE ((t.kind)::text = 'ENGAGEMENT'::text)) AS engaged
           FROM (public.finance_financialtransaction t
             JOIN node_root nr ON ((nr.id = t.program_node_id)))
          WHERE ((t.program_node_id IS NOT NULL) AND ((t.status)::text = 'CONSOLIDATED'::text))
          GROUP BY t.project_id, nr.root_id, t.fiscal_year
        )
 SELECT s.project_id,
    s.root_id AS program_node_id,
    s.root_code AS component_code,
    s.root_name AS component_name,
    s.fiscal_year,
    bt.budget_total,
    COALESCE(tx.engaged, (0)::numeric) AS engaged_year,
    COALESCE(tx.disbursed, (0)::numeric) AS disbursed_year,
    COALESCE(tx.realised, (0)::numeric) AS realised_year,
    sum(COALESCE(tx.disbursed, (0)::numeric)) OVER w AS disbursed_cumulative,
    sum(COALESCE(tx.realised, (0)::numeric)) OVER w AS realised_cumulative,
        CASE
            WHEN ((bt.budget_total IS NULL) OR (bt.budget_total = (0)::numeric)) THEN NULL::numeric
            ELSE round(((100.0 * sum(COALESCE(tx.disbursed, (0)::numeric)) OVER w) / bt.budget_total), 1)
        END AS disbursement_rate,
        CASE
            WHEN ((bt.budget_total IS NULL) OR (bt.budget_total = (0)::numeric)) THEN NULL::numeric
            ELSE round(((100.0 * sum(COALESCE(tx.realised, (0)::numeric)) OVER w) / bt.budget_total), 1)
        END AS financial_realisation_rate,
    (bt.budget_total - sum(COALESCE(tx.disbursed, (0)::numeric)) OVER w) AS reliquat_disbursed
   FROM ((spine s
     LEFT JOIN budget_total bt ON (((bt.project_id = s.project_id) AND (bt.root_id = s.root_id))))
     LEFT JOIN tx ON (((tx.project_id = s.project_id) AND (tx.root_id = s.root_id) AND (tx.fiscal_year = s.fiscal_year))))
  WINDOW w AS (PARTITION BY s.project_id, s.root_id ORDER BY s.fiscal_year ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);


ALTER VIEW public.v_financial_by_component OWNER TO mse_app;

--
-- Name: v_grievance_sla; Type: VIEW; Schema: public; Owner: mse_app
--

CREATE VIEW public.v_grievance_sla AS
 WITH g AS (
         SELECT gr.project_id,
            gr.grievance_type_id,
            gt.code AS type_code,
            gt.name AS type_name,
            gr.level,
            gr.state,
            gr.received_at,
            gr.resolved_at,
                CASE
                    WHEN (gr.resolved_at IS NOT NULL) THEN ((gr.resolved_at - gr.received_at) <= COALESCE(gt.sla_days, pj.grievance_sla_days))
                    ELSE NULL::boolean
                END AS within_sla
           FROM ((public.grievances_grievance gr
             JOIN public.grievances_grievancetype gt ON ((gt.id = gr.grievance_type_id)))
             JOIN public.core_project pj ON ((pj.id = gr.project_id)))
          WHERE ((gr.status)::text = 'CONSOLIDATED'::text)
        )
 SELECT project_id,
    grievance_type_id,
    type_code,
    type_name,
    level,
    count(*) AS total,
    count(*) FILTER (WHERE ((state)::text = 'RECEIVED'::text)) AS received,
    count(*) FILTER (WHERE ((state)::text = 'IN_PROGRESS'::text)) AS in_progress,
    count(*) FILTER (WHERE ((state)::text = ANY ((ARRAY['RESOLVED'::character varying, 'CLOSED'::character varying])::text[]))) AS resolved,
    count(*) FILTER (WHERE ((state)::text = 'REJECTED'::text)) AS rejected,
    count(*) FILTER (WHERE within_sla) AS resolved_within_sla,
        CASE
            WHEN (count(*) FILTER (WHERE (resolved_at IS NOT NULL)) = 0) THEN NULL::numeric
            ELSE round(((100.0 * (count(*) FILTER (WHERE within_sla))::numeric) / (count(*) FILTER (WHERE (resolved_at IS NOT NULL)))::numeric), 1)
        END AS sla_rate
   FROM g
  GROUP BY project_id, grievance_type_id, type_code, type_name, level;


ALTER VIEW public.v_grievance_sla OWNER TO mse_app;

--
-- Name: v_impact_change; Type: VIEW; Schema: public; Owner: mse_app
--

CREATE VIEW public.v_impact_change AS
 WITH impact_meas AS (
         SELECT meas.project_id,
            meas.indicator_id,
            meas.geo_unit_id,
            meas.period_year,
            meas.period_quarter,
            meas.period_month,
            meas.value,
            meas.id
           FROM ((public.indicators_measurement meas
             JOIN public.indicators_indicator ind_1 ON ((ind_1.id = meas.indicator_id)))
             JOIN public.indicators_indicatortype it ON ((it.id = ind_1.indicator_type_id)))
          WHERE (((it.code)::text = 'IMPACT'::text) AND ((meas.status)::text = 'CONSOLIDATED'::text))
        ), ordered AS (
         SELECT im.project_id,
            im.indicator_id,
            im.geo_unit_id,
            im.period_year,
            im.period_quarter,
            im.period_month,
            im.value,
            im.id,
            row_number() OVER (PARTITION BY im.indicator_id, im.geo_unit_id ORDER BY im.period_year, im.period_quarter NULLS FIRST, im.period_month NULLS FIRST, im.id) AS rn_asc,
            row_number() OVER (PARTITION BY im.indicator_id, im.geo_unit_id ORDER BY im.period_year DESC, im.period_quarter DESC NULLS LAST, im.period_month DESC NULLS LAST, im.id DESC) AS rn_desc
           FROM impact_meas im
        ), baseline AS (
         SELECT ordered.indicator_id,
            ordered.geo_unit_id,
            ordered.value AS baseline_value,
            ordered.period_year AS baseline_year
           FROM ordered
          WHERE (ordered.rn_asc = 1)
        ), latest AS (
         SELECT ordered.indicator_id,
            ordered.geo_unit_id,
            ordered.value AS latest_value,
            ordered.period_year AS latest_year
           FROM ordered
          WHERE (ordered.rn_desc = 1)
        )
 SELECT ind.project_id,
    ind.id AS indicator_id,
    ind.code AS indicator_code,
    ind.name AS indicator_name,
    ind.unit,
    ind.direction,
    b.geo_unit_id,
    gu.name AS geo_name,
    b.baseline_value,
    b.baseline_year,
    l.latest_value,
    l.latest_year,
    (l.latest_value - b.baseline_value) AS change_abs,
        CASE
            WHEN ((b.baseline_value IS NULL) OR (b.baseline_value = (0)::numeric)) THEN NULL::numeric
            ELSE round(((100.0 * (l.latest_value - b.baseline_value)) / abs(b.baseline_value)), 1)
        END AS change_pct,
    tn.target_value
   FROM ((((baseline b
     JOIN latest l ON (((l.indicator_id = b.indicator_id) AND (NOT (l.geo_unit_id IS DISTINCT FROM b.geo_unit_id)))))
     JOIN public.indicators_indicator ind ON ((ind.id = b.indicator_id)))
     LEFT JOIN public.geo_geounit gu ON ((gu.id = b.geo_unit_id)))
     LEFT JOIN LATERAL ( SELECT t.value AS target_value
           FROM (public.indicators_indicatortarget t
             JOIN public.core_milestone ms ON ((ms.id = t.milestone_id)))
          WHERE ((t.indicator_id = b.indicator_id) AND (NOT (t.geo_unit_id IS DISTINCT FROM b.geo_unit_id)))
          ORDER BY ms."order" DESC
         LIMIT 1) tn ON (true));


ALTER VIEW public.v_impact_change OWNER TO mse_app;

--
-- Name: v_indicator_progress; Type: VIEW; Schema: public; Owner: mse_app
--

CREATE VIEW public.v_indicator_progress AS
 WITH consolidated AS (
         SELECT meas.project_id,
            meas.indicator_id,
            meas.geo_unit_id,
            meas.period_year,
            meas.period_quarter,
            meas.period_month,
            meas.period_date,
            meas.value,
            meas.id
           FROM public.indicators_measurement meas
          WHERE ((meas.status)::text = 'CONSOLIDATED'::text)
        ), per_period AS (
         SELECT c.project_id,
            c.indicator_id,
            c.geo_unit_id,
            c.period_year,
            c.period_quarter,
            ind_1.aggregation_method,
            sum(c.value) AS sum_val,
            avg(c.value) AS avg_val,
            max(c.value) AS max_val,
            min(c.value) AS min_val,
            (array_agg(c.value ORDER BY c.period_month DESC NULLS LAST, c.period_date DESC NULLS LAST, c.id DESC))[1] AS last_val
           FROM (consolidated c
             JOIN public.indicators_indicator ind_1 ON ((ind_1.id = c.indicator_id)))
          GROUP BY c.project_id, c.indicator_id, c.geo_unit_id, c.period_year, c.period_quarter, ind_1.aggregation_method
        ), period_value AS (
         SELECT pp.project_id,
            pp.indicator_id,
            pp.geo_unit_id,
            pp.period_year,
            pp.period_quarter,
            pp.aggregation_method,
            pp.sum_val,
            pp.avg_val,
            pp.max_val,
            pp.min_val,
            pp.last_val,
                CASE pp.aggregation_method
                    WHEN 'SUM'::text THEN pp.sum_val
                    WHEN 'AVERAGE'::text THEN pp.avg_val
                    WHEN 'MAX'::text THEN pp.max_val
                    WHEN 'MIN'::text THEN pp.min_val
                    ELSE pp.last_val
                END AS period_value
           FROM per_period pp
        ), cumulative AS (
         SELECT pv.project_id,
            pv.indicator_id,
            pv.geo_unit_id,
            pv.period_year,
            pv.period_quarter,
            pv.aggregation_method,
            pv.sum_val,
            pv.avg_val,
            pv.max_val,
            pv.min_val,
            pv.last_val,
            pv.period_value,
                CASE pv.aggregation_method
                    WHEN 'SUM'::text THEN sum(pv.period_value) OVER w
                    WHEN 'AVERAGE'::text THEN avg(pv.period_value) OVER w
                    WHEN 'MAX'::text THEN max(pv.period_value) OVER w
                    WHEN 'MIN'::text THEN min(pv.period_value) OVER w
                    ELSE last_value(pv.period_value) OVER w
                END AS cumulative_value
           FROM period_value pv
          WINDOW w AS (PARTITION BY pv.indicator_id, pv.geo_unit_id ORDER BY pv.period_year, pv.period_quarter NULLS FIRST ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
        ), target_geo AS (
         SELECT DISTINCT ON (t.indicator_id, t.geo_unit_id) t.indicator_id,
            t.geo_unit_id,
            t.value AS target_value
           FROM (public.indicators_indicatortarget t
             JOIN public.core_milestone ms ON ((ms.id = t.milestone_id)))
          ORDER BY t.indicator_id, t.geo_unit_id, ms."order" DESC
        ), target_national AS (
         SELECT DISTINCT ON (t.indicator_id) t.indicator_id,
            t.value AS target_value
           FROM (public.indicators_indicatortarget t
             JOIN public.core_milestone ms ON ((ms.id = t.milestone_id)))
          WHERE (t.geo_unit_id IS NULL)
          ORDER BY t.indicator_id, ms."order" DESC
        )
 SELECT cu.project_id,
    cu.indicator_id,
    ind.code AS indicator_code,
    ind.name AS indicator_name,
    it.code AS indicator_type,
    ind.unit,
    ind.direction,
    ind.program_node_id,
    pn.code AS program_code,
    cu.geo_unit_id,
    gu.name AS geo_name,
    gl.rank AS geo_rank,
    cu.period_year,
    cu.period_quarter,
    cu.period_value,
    cu.cumulative_value,
    COALESCE(tg.target_value, tn.target_value) AS target_value,
        CASE
            WHEN ((COALESCE(tg.target_value, tn.target_value) IS NULL) OR (COALESCE(tg.target_value, tn.target_value) = (0)::numeric)) THEN NULL::numeric
            ELSE round(((100.0 * cu.cumulative_value) / COALESCE(tg.target_value, tn.target_value)), 1)
        END AS achievement_rate,
        CASE
            WHEN ((COALESCE(tg.target_value, tn.target_value) IS NULL) OR (COALESCE(tg.target_value, tn.target_value) = (0)::numeric)) THEN 'GREY'::text
            WHEN ((ind.direction)::text = 'INCREASE'::text) THEN
            CASE
                WHEN (((100.0 * cu.cumulative_value) / COALESCE(tg.target_value, tn.target_value)) >= (90)::numeric) THEN 'GREEN'::text
                WHEN (((100.0 * cu.cumulative_value) / COALESCE(tg.target_value, tn.target_value)) >= (60)::numeric) THEN 'AMBER'::text
                ELSE 'RED'::text
            END
            ELSE
            CASE
                WHEN (cu.cumulative_value = (0)::numeric) THEN 'GREEN'::text
                WHEN (((100.0 * COALESCE(tg.target_value, tn.target_value)) / cu.cumulative_value) >= (90)::numeric) THEN 'GREEN'::text
                WHEN (((100.0 * COALESCE(tg.target_value, tn.target_value)) / cu.cumulative_value) >= (60)::numeric) THEN 'AMBER'::text
                ELSE 'RED'::text
            END
        END AS rag_status
   FROM (((((((cumulative cu
     JOIN public.indicators_indicator ind ON ((ind.id = cu.indicator_id)))
     JOIN public.indicators_indicatortype it ON ((it.id = ind.indicator_type_id)))
     LEFT JOIN public.program_programnode pn ON ((pn.id = ind.program_node_id)))
     LEFT JOIN public.geo_geounit gu ON ((gu.id = cu.geo_unit_id)))
     LEFT JOIN public.geo_geolevel gl ON ((gl.id = gu.geo_level_id)))
     LEFT JOIN target_geo tg ON (((tg.indicator_id = cu.indicator_id) AND (NOT (tg.geo_unit_id IS DISTINCT FROM cu.geo_unit_id)))))
     LEFT JOIN target_national tn ON ((tn.indicator_id = cu.indicator_id)));


ALTER VIEW public.v_indicator_progress OWNER TO mse_app;

--
-- Name: v_procurement_durations; Type: VIEW; Schema: public; Owner: mse_app
--

CREATE VIEW public.v_procurement_durations AS
 SELECT pp.project_id,
    se.procurement_process_id,
    pp.designation,
    se.procurement_stage_id,
    ps.code AS stage_code,
    ps.name AS stage_name,
    ps."order" AS stage_order,
    se.start_date,
    se.end_date,
    se.deadline,
    (se.end_date - se.start_date) AS duration_days,
        CASE
            WHEN ((se.end_date IS NULL) AND (se.start_date IS NOT NULL)) THEN (CURRENT_DATE - se.start_date)
            ELSE NULL::integer
        END AS days_elapsed_open,
    ((se.deadline IS NOT NULL) AND (se.end_date IS NULL) AND (CURRENT_DATE > se.deadline)) AS is_overdue
   FROM ((public.procurement_stageevent se
     JOIN public.procurement_procurementprocess pp ON ((pp.id = se.procurement_process_id)))
     JOIN public.procurement_procurementstage ps ON ((ps.id = se.procurement_stage_id)))
  WHERE ((pp.status)::text = 'CONSOLIDATED'::text);


ALTER VIEW public.v_procurement_durations OWNER TO mse_app;

--
-- Name: v_procurement_status; Type: VIEW; Schema: public; Owner: mse_app
--

CREATE VIEW public.v_procurement_status AS
 WITH planned AS (
         SELECT procurement_ppmitem.project_id,
            procurement_ppmitem.expense_category_id,
            procurement_ppmitem.procurement_method_id,
            count(*) AS planned_count,
            COALESCE(sum(procurement_ppmitem.planned_amount), (0)::numeric) AS planned_amount
           FROM public.procurement_ppmitem
          WHERE procurement_ppmitem.is_active
          GROUP BY procurement_ppmitem.project_id, procurement_ppmitem.expense_category_id, procurement_ppmitem.procurement_method_id
        ), processes AS (
         SELECT procurement_procurementprocess.project_id,
            procurement_procurementprocess.expense_category_id,
            procurement_procurementprocess.procurement_method_id,
            count(*) AS process_count,
            count(*) FILTER (WHERE procurement_procurementprocess.is_completed) AS completed_count,
            count(*) FILTER (WHERE (NOT procurement_procurementprocess.is_completed)) AS in_progress_count,
            COALESCE(sum(procurement_procurementprocess.awarded_amount) FILTER (WHERE procurement_procurementprocess.is_completed), (0)::numeric) AS awarded_amount,
            COALESCE(sum(COALESCE(procurement_procurementprocess.awarded_amount, procurement_procurementprocess.estimated_amount)), (0)::numeric) AS engaged_amount
           FROM public.procurement_procurementprocess
          WHERE ((procurement_procurementprocess.status)::text = 'CONSOLIDATED'::text)
          GROUP BY procurement_procurementprocess.project_id, procurement_procurementprocess.expense_category_id, procurement_procurementprocess.procurement_method_id
        )
 SELECT COALESCE(p.project_id, pr.project_id) AS project_id,
    COALESCE(p.expense_category_id, pr.expense_category_id) AS expense_category_id,
    ec.code AS category_code,
    ec.name AS category_name,
    COALESCE(p.procurement_method_id, pr.procurement_method_id) AS procurement_method_id,
    pm.code AS method_code,
    pm.name AS method_name,
    COALESCE(p.planned_count, (0)::bigint) AS planned_count,
    COALESCE(p.planned_amount, (0)::numeric) AS planned_amount,
    COALESCE(pr.process_count, (0)::bigint) AS process_count,
    COALESCE(pr.completed_count, (0)::bigint) AS completed_count,
    COALESCE(pr.in_progress_count, (0)::bigint) AS in_progress_count,
    COALESCE(pr.awarded_amount, (0)::numeric) AS awarded_amount,
    COALESCE(pr.engaged_amount, (0)::numeric) AS engaged_amount,
        CASE
            WHEN (COALESCE(p.planned_count, (0)::bigint) = 0) THEN NULL::numeric
            ELSE round(((100.0 * (COALESCE(pr.completed_count, (0)::bigint))::numeric) / (p.planned_count)::numeric), 1)
        END AS realisation_rate_count
   FROM (((planned p
     FULL JOIN processes pr ON (((p.project_id = pr.project_id) AND (NOT (p.expense_category_id IS DISTINCT FROM pr.expense_category_id)) AND (NOT (p.procurement_method_id IS DISTINCT FROM pr.procurement_method_id)))))
     LEFT JOIN public.finance_expensecategory ec ON ((ec.id = COALESCE(p.expense_category_id, pr.expense_category_id))))
     LEFT JOIN public.procurement_procurementmethod pm ON ((pm.id = COALESCE(p.procurement_method_id, pr.procurement_method_id))));


ALTER VIEW public.v_procurement_status OWNER TO mse_app;

